#!/usr/bin/env bash
# Copyright 2026 RegaliumOS™.
# SPDX-License-Identifier: Apache-2.0

# Renders the Homebrew formula for VERSION from the release archives' .sha256
# files in DIR. Used by the release workflow; runnable by hand to re-render.
#
#   tools/bacnet-probe/dist/formula.sh 0.1.0 dist > bacnet-probe.rb
set -euo pipefail
version="$1"
dir="$2"
base="https://github.com/regalium-os/bacnet-rs/releases/download/bacnet-probe-v${version}"

sha() { cut -d' ' -f1 "${dir}/bacnet-probe-${version}-$1.tar.gz.sha256"; }
asset() {
    printf '      url "%s/bacnet-probe-%s-%s.tar.gz"\n      sha256 "%s"\n' "$base" "$version" "$1" "$(sha "$1")"
}

cat <<RUBY
# Generated by tools/bacnet-probe/dist/formula.sh in regalium-os/bacnet-rs.
class BacnetProbe < Formula
  desc "Discover, browse, watch and export BACnet/IP devices"
  homepage "https://github.com/regalium-os/bacnet-rs/tree/main/tools/bacnet-probe"
  version "${version}"
  license "Apache-2.0"

  on_macos do
    on_arm do
$(asset aarch64-apple-darwin)
    end
    on_intel do
$(asset x86_64-apple-darwin)
    end
  end

  on_linux do
    on_arm do
$(asset aarch64-unknown-linux-gnu)
    end
    on_intel do
$(asset x86_64-unknown-linux-gnu)
    end
  end

  def install
    bin.install "bacnet-probe"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/bacnet-probe --version")
    packet = "81 0a 00 11 01 04 00 05 01 0c 0c 02 00 02 57 19 4d"
    assert_match "readProperty device:599 object-name", shell_output("#{bin}/bacnet-probe dissect '#{packet}'")
  end
end
RUBY
